-- Public observations exported from the former Sites /api/v2/history on 2026-11-08.
-- Keep archival chart data separate from publish revisions and notification queues.
CREATE TABLE legacy_public_history (id INTEGER PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE public_history_exclusions (
  revision_id INTEGER NOT NULL,
  published_at TEXT NOT NULL,
  PRIMARY KEY (revision_id, published_at)
);
-- The owner rolled back this test publish. Keep its admin audit record.
SELECT id,published_at FROM revisions
WHERE id=3 AND published_at='2026-11-08T08:33:29.976Z'
  AND EXISTS (SELECT 1 FROM json_each(payload,'$.quotes') WHERE json_extract(value,'$.direction')='thb_mmk' AND json_extract(value,'$.rate_micros')=83333333)
  AND EXISTS (SELECT 1 FROM json_each(payload,'$.quotes') WHERE json_extract(value,'$.direction')='mmk_thb' AND json_extract(value,'$.rate_micros')=100000000);
